	/** The production executor stays live; every task owned by this probe is released and joined even after failure. */
	private static final class SaturatedPool implements AutoCloseable {
		private final ThreadPoolExecutor executor;
		private final CountDownLatch release = new CountDownLatch(1);
		private final List<Future<?>> jobs = new ArrayList<>();

		private SaturatedPool(ThreadPoolExecutor executor) {
			this.executor = executor;
		}

		private void occupyWorkersAndQueue() throws InterruptedException {
			int workers = executor.getMaximumPoolSize();
			assertThat(executor.getCorePoolSize()).as("production uses a fixed-size bounded pool").isEqualTo(workers);
			assertThat(executor.getQueue().remainingCapacity()).isLessThan(Integer.MAX_VALUE);
			CountDownLatch entered = new CountDownLatch(workers);
			for (int worker = 0; worker < workers; worker++) {
				jobs.add(executor.submit(() -> {
					entered.countDown();
					try {
						release.await();
					} catch (InterruptedException interrupted) {
						Thread.currentThread().interrupt();
						throw new AssertionError("owned pool blocker interrupted", interrupted);
					}
				}));
			}
			entered.await();
			int queuedJobs = executor.getQueue().remainingCapacity();
			for (int queued = 0; queued < queuedJobs; queued++) {
				jobs.add(executor.submit(() -> {
				}));
			}
			assertThat(executor.getQueue().remainingCapacity()).isZero();
			System.out.println("STARTUP_REJECTION_SATURATED workers=" + workers + " queuedJobs=" + queuedJobs);
		}

		@Override
		public void close() {
			release.countDown();
			boolean interrupted = false;
			Throwable failure = null;
			for (Future<?> job : jobs) {
				boolean settled = false;
				while (!settled) {
					try {
						job.get();
						settled = true;
					} catch (InterruptedException signal) {
						interrupted = true;
					} catch (ExecutionException problem) {
						settled = true;
						if (failure == null) {
							failure = problem;
						} else {
							failure.addSuppressed(problem);
						}
					}
				}
			}
			if (interrupted) {
				Thread.currentThread().interrupt();
			}
			if (failure != null) {
				throw new AssertionError("owned saturation tasks failed to settle", failure);
			}
		}
	}

